"""Build a local, self-contained visual review of frozen results."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'evidence/detection-round2'
NAMES={'craft-base':'CRAFT · original scale','craft-scale3':'CRAFT · enlarged only','craft-selective':'CRAFT · rotation agreement','craft-compact':'CRAFT · selective extra scale','symbols-base':'Current symbols + junctions','symbols-dark':'Darker ink cutoff','symbols-thick':'Thick stroke groups','trails-base':'Trails · projection order','trails-dark':'Trails · darker ink','trails-thick':'Trails · thick strokes','trails-graph':'Trails · full graph walks','trails-safe':'Trails · supported links'}
def main():
 summary=json.loads((OUT/'summary.json').read_text('utf-8'));data=json.loads((OUT/'review-data.json').read_text('utf-8'));tables=[]
 for prefix,title in [('craft','Unread text regions'),('symbols','Unknown symbols'),('trails','Trail segments')]:
  rows=[]
  for key,s in summary.items():
   if not s['method'].startswith(prefix):continue
   marks='—' if prefix=='trails' else f"{s['mark_hits']}/{s['mark_total']}"
   bad=s['topology']['unsupported_edges'] if s['method'] in ('trails-base','trails-safe','trails-graph') else '—'
   rows.append(f'<tr><th>{NAMES[s["method"]]}</th><td>{s["split"]}</td><td>{marks}</td><td>{s["total_proposals"]}</td><td>{s["median_proposals"]:g}</td><td>{s["median_ms"]:.0f}</td><td>{bad}</td></tr>')
  tables.append(f'<h2>{title}</h2><div class="scroll"><table><thead><tr><th>Method</th><th>Scene group</th><th>Located marks</th><th>All proposals</th><th>Median / tile</th><th>Median ms / tile</th><th>Unaccepted links</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>')
 payload=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
 report='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detection round 2 · Mapwalker</title><style>
 body{margin:0;background:#f7f6ef;color:#173e35;font:16px/1.55 system-ui}main{max-width:1180px;margin:auto;padding:28px}h1{font:42px Georgia;margin:10px 0}h2{font:27px Georgia;margin-top:32px}a{color:#17695b}.intro{max-width:950px}.notice{padding:16px 20px;background:#eee5cc;border-left:4px solid #a17b24}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.stat{background:white;padding:18px;border:1px solid #dce1d4;border-radius:8px}.stat strong{display:block;font:30px Georgia}.stat span{font-size:14px}.controls{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0;align-items:end}label{display:flex;flex-direction:column;font-size:14px;gap:5px}select{padding:9px;max-width:390px;font:inherit}.check{flex-direction:row;align-items:center}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}section{min-width:0}canvas{width:100%;height:auto;border:1px solid #d9ddcc;cursor:crosshair}.count{font-size:14px;min-height:25px}h3{font-size:17px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;background:white;font-size:14px}td,th{padding:9px;border-bottom:1px solid #dce1d4;text-align:left}th{font-weight:600}small{color:#637669}.crop{display:flex;gap:20px;padding:18px;background:white;margin-top:24px;align-items:center}.crop canvas{width:160px;height:160px;flex:none}.decisions li{margin-bottom:12px}.refs{margin-top:24px} @media(max-width:760px){main{padding:16px}.stats{grid-template-columns:1fr}.grid{gap:12px}.crop{align-items:start}h1{font-size:32px}select{max-width:95vw}}
 </style><main><a href="/">← Mapwalker</a> · <a href="../symbol-first/report.html">Previous detection experiment</a><h1>More readable marks. Fewer invented trail links.</h1>
 <p class="intro">Wulai · both historical series · 23 padded map scenes · GTX 1650 · 29 September 2026. These are candidate regions and segments for review. No recognizer, known place name or reference annotation was used to produce them.</p>
 <div class="stats"><div class="stat"><strong>7 → 8 / 10</strong><span>Known development marks located by text regions. ウ added; original 社 retained.</span></div><div class="stat"><strong>900 → 0</strong><span>Drawn trail links absent from the accepted dash graph, across 23 scenes. A geometry check, not trail accuracy.</span></div><div class="stat"><strong>1,165 → 293</strong><span>Predicted pixels outside the traced corridor in one review region. Its reference coverage stays 23%.</span></div></div>
 <div class="notice"><strong>Still incomplete.</strong> Text-region detection does not read the labels. 溪 and the hot-spring mark remain misses in the text-region check. Contours still produce false proposals, particularly in the 1916 scans. The symbol alternatives lose useful marks; they are not replacements for the current symbol generators.</div>
 <h2 id="compare">Inspect the actual pixels</h2><p>Blue boxes: unread text regions. Teal: shape proposals. Purple: trail segments. Dashed green: partial evaluation references. Click a box to see its source crop. Choose “Trails” and the first fresh southwest scene to inspect the traced chain.</p>
 <div class="controls"><label>Feature<select id="feature"><option value="text">Text regions</option><option value="symbols">Symbols</option><option value="trails">Trails</option></select></label><label>Map scene<select id="scene"></select></label><label class="check"><input id="refs" type="checkbox" checked> Evaluation references</label><label class="check"><input id="repeats" type="checkbox"> Excluded repetitions</label></div>
 <div class="grid"><section><label>Before / baseline<select id="left-method"></select></label><p class="count" id="left-count"></p><canvas id="left" width="384" height="384" aria-label="Baseline map proposals"></canvas></section><section><label>After / experiment<select id="right-method"></select></label><p class="count" id="right-count"></p><canvas id="right" width="384" height="384" aria-label="Candidate map proposals"></canvas></section></div>
 <label class="refs">Inspect an after-region<select id="inspect"><option value="">Choose a proposed region</option></select></label><div class="crop"><canvas id="crop" width="160" height="160" aria-label="Original pixels of selected proposal"></canvas><div><strong>Original map evidence</strong><p id="crop-info">Select a proposed region above. A mark can remain useful even when its name is unreadable.</p></div></div>
 <h2>Decisions</h2><ul class="decisions"><li><strong>Land supported trail links:</strong> retain the existing dash detector and straight-segment gate; split its output whenever consecutive dashes lack an accepted local graph edge. It cannot add a new connecting line. This reduces misleading geometry, but does not find the full trail.</li><li><strong>Add experimental text regions:</strong> keep scale2 CRAFT regions and add compact scale3 regions with peak ≥0.5, maximum side 96 native pixels, and no baseline overlap. This is a development-selected heuristic, not a correctness probability. The four second-holdout scenes retain 2/2 annotated labels, with 31 → 36 proposals. The feature has its own tile/algorithm fingerprint and uses the configured local GPU runtime.</li><li><strong>Reject darker ink as a replacement:</strong> it loses most known marks (5/10 → 1/10 for symbols) and the traced chain. <strong>Retain thick-stroke symbols for research:</strong> fewer proposals, but different misses and 3/3 → 2/3 on the first fresh glyph examples. <strong>Reject broad graph walks and rotation agreement for this release:</strong> the former adds review burden; the latter fails to recover ウ.</li></ul>
 <p>CRAFT inference is roughly 5 seconds per padded tile, plus isolated model startup. Each job releases the GPU process afterward. The first isolated two-scale job peaked at 3,757 MiB, above the target. Releasing unused CUDA cache between rotations reduced the repeated check to 2,615 MiB (2.55 GiB), with unchanged regions. Wall time was about 12 seconds including 5.8 seconds of startup. Processing stays sequential. The live worker records full startup and inference timing separately.</p>
 <h2>What these measurements can establish</h2><p>The ten older boxes, three first-fresh glyph boxes, two second-holdout labels, and one traced chain are partial manual references. Box matching requires IoU ≥0.25. The trace uses a fixed 6px corridor. Unlabeled regions elsewhere are unassessed, not automatically false. The second holdout was gathered after candidate selection, but adjacent tile halos overlap some earlier context; it is not a fully spatially independent accuracy test. There is no general precision/recall claim, no verified symbol classification, and no complete hiking-route reconstruction.</p>
 <p>“Unaccepted links” checks correspondence to the detector’s own local graph only. The separate manually traced corridor exposes how much false-looking geometry remains. Rejected results are preserved below. Timing excludes image decoding for comparison; the selective scale totals include both original runs and combination work. Symbol/trail variants run on CPU. The safe-trail prototype builds its graph twice; production shares the graph and matches its geometry exactly.</p>
 '''+''.join(tables)+'''
 <h2>Reviewable evidence</h2><p><a href="conclusions.md">Findings and replay notes</a> · <a href="CONTRACT.md">Contract and hypotheses</a> · <a href="manifest-audit.json">Input manifest audit</a> · <a href="isolated-backend.json">GPU memory and startup</a> · <a href="summary.json">All measurements</a> · <a href="inputs.json">First 19 input identities</a> · <a href="holdout-inputs.json">Second holdout identities</a> · <a href="fresh-references.json">First fresh references</a> · <a href="holdout-references.json">Second holdout references</a> · <a href="production-parity.json">Production parity on all 23 scenes</a> · <a href="verification.json">Regression and live checks</a></p><p>Raw per-angle boxes, paths, run metadata, and exact harness snapshots are stored beside this report. Modern exclusion and map coordinates are applied by the existing publication pipeline after detection. Reviews and saved readings remain separate; no reference answers are inserted into POIs.</p></main>
 <script>const data='''+payload+''';const names='''+json.dumps(NAMES)+''';const $=id=>document.getElementById(id);const lists={text:['craft-base','craft-compact','craft-scale3','craft-selective'],symbols:['symbols-base','symbols-thick','symbols-dark'],trails:['trails-base','trails-safe','trails-graph','trails-thick','trails-dark']};let selectedImage=null,visible={},renderGeneration=0;for(let i=0;i<data.scenes.length;i++){const s=data.scenes[i];$('scene').add(new Option(s.split+' · '+s.id+' · '+s.x+'/'+s.y,i))}function keep(p){return !p.repeating||p.details?.trail_context}function methods(){const list=lists[$('feature').value];for(const side of ['left','right']){const e=$(side+'-method');e.replaceChildren();for(const m of list)e.add(new Option(names[m],m));e.value=side==='left'?list[0]:list[1]}render()}function render(){const generation=++renderGeneration;const s=data.scenes[+$('scene').value],im=new Image();im.onload=()=>{if(generation!==renderGeneration)return;selectedImage=im;for(const side of ['left','right']){const m=$(side+'-method').value,row=data.results[m+'-'+s.split]?.find(r=>r.scene===s.id),all=row?.proposals||[],ps=all.filter(p=>$('repeats').checked||keep(p));visible[side]=ps;const ctx=$(side).getContext('2d');ctx.drawImage(im,0,0,384,384);ctx.lineWidth=1.5;for(const p of ps){ctx.strokeStyle=!keep(p)?'#888':p.kind==='trail'?'#7648ad':p.kind==='symbol'?'#087e70':'#2266c4';if(p.kind==='trail'){const path=p.details.pixel_path;ctx.beginPath();path.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.stroke()}else{const b=p.box;ctx.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1])}}if($('refs').checked){const refs=data.references[s.split];ctx.strokeStyle='#129b36';ctx.lineWidth=2;ctx.setLineDash([5,3]);for(const p of refs.marks||[])if(p.scene===s.id){const b=p.box;ctx.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1])}for(const p of refs.paths||[])if(p.scene===s.id){ctx.beginPath();p.points.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.stroke()}ctx.setLineDash([])}$(side+'-count').textContent=row?all.filter(keep).length+' candidates · '+Math.round(row.total_inference_ms)+' ms · '+all.filter(p=>!keep(p)).length+' repetition flags':'Not run: candidate rejected or not selected for this scene group';}const picker=$('inspect');picker.replaceChildren(new Option('Choose a proposed region',''));for(let i=0;i<visible.right.length;i++){const p=visible.right[i];picker.add(new Option('Region '+(i+1)+' · '+p.kind+' · score '+p.score.toFixed(2),i))} $('crop-info').textContent='Choose a proposed region to inspect its original pixels.';$('crop').getContext('2d').clearRect(0,0,160,160);};im.src=s.path}for(const side of ['left','right']){$(side).onclick=e=>{const b=e.currentTarget.getBoundingClientRect(),x=(e.clientX-b.left)*384/b.width,y=(e.clientY-b.top)*384/b.height;const ps=visible[side].filter(p=>x>=p.box[0]&&x<=p.box[2]&&y>=p.box[1]&&y<=p.box[3]).sort((a,b)=>(a.box[2]-a.box[0])*(a.box[3]-a.box[1])-(b.box[2]-b.box[0])*(b.box[3]-b.box[1]));if(!ps.length)return;const p=ps[0],q=p.box,sz=Math.max(q[2]-q[0],q[3]-q[1])+20,ctx=$('crop').getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,160,160);ctx.drawImage(selectedImage,(q[0]+q[2]-sz)/2,(q[1]+q[3]-sz)/2,sz,sz,0,0,160,160);$('crop-info').textContent=names[$(side+'-method').value]+' · '+(p.kind==='trail'?'candidate dash chain':p.kind==='symbol'?'unclassified mark':'unread text region')+' · score '+p.score.toFixed(3)+'. No name inferred.'};$(side+'-method').onchange=render}$('inspect').onchange=()=>{if($('inspect').value==='')return;const p=visible.right[+$('inspect').value],q=p.box,sz=Math.max(q[2]-q[0],q[3]-q[1])+20,ctx=$('crop').getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,160,160);ctx.drawImage(selectedImage,(q[0]+q[2]-sz)/2,(q[1]+q[3]-sz)/2,sz,sz,0,0,160,160);$('crop-info').textContent=names[$('right-method').value]+' · '+p.kind+' candidate · score '+p.score.toFixed(3)+'. No name inferred.'};$('feature').onchange=methods;$('scene').onchange=render;$('refs').onchange=render;$('repeats').onchange=render;methods();</script></html>'''
 (OUT/'report.html').write_text(report,'utf-8')
 print('Wrote review report')
if __name__=='__main__':main()
